package com.coffeeshop.service;import com.coffeeshop.model.AuditModels;import com.coffeeshop.repository.AuditRepository;import org.junit.jupiter.api.Test;import java.time.LocalDate;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class AuditServiceTest{private final Stub repo=new Stub();private final AuditService service=new AuditService(repo);@Test void validatesAndDelegates(){LocalDate n=LocalDate.now();service.entries(" action ",n.minusDays(2),n);assertEquals("action",repo.search);}@Test void rejectsInvalidRanges(){LocalDate n=LocalDate.now();assertThrows(IllegalArgumentException.class,()->service.entries("",null,n));assertThrows(IllegalArgumentException.class,()->service.entries("",n,n.minusDays(1)));assertThrows(IllegalArgumentException.class,()->service.entries("",n.minusYears(2),n));}private static final class Stub implements AuditRepository{String search;public List<AuditModels.Entry>find(String s,LocalDate f,LocalDate t){search=s;return List.of();}}}
